using System;using System.Collections;using System.IO;using System.Security.Cryptography;using System.Runtime.InteropServices;
using UnityEngine;using LighFight.Runtime;using SourceContact;using LazySourceContact;
namespace SourceContactReview {
 // Review-only detector. Does not write transforms, weights, animation, colliders, damage or cameras.
 public sealed class SourceSurfaceReviewAdapter:MonoBehaviour,IActorCurveWarmup {
  public SkinnedMeshRenderer sourceSkin;public TextAsset originalMeshFixture,compactFixture,allInfluencesFixture,originalBoneNames;
  public const string MeshSha="bfeae8add38cd7defe59da62136010acfeb9769e5cca581cb3b112f908791ede";
  public const string CompactSha="06da517163fb538265d3dd3a7179e4dd373763f5b4e376a41b9bb7d99278f7cd";
  public const string HullSha="22aad0de0730a458614bbab30441d75d95264823c795db1e5c8ca43cec934791";
  public LazySurface Surface {get;private set;}public ContainmentTopology MainTopology {get;private set;}public bool IsWarm=>Surface!=null;
  Transform[] bones;Matrix4x4[] binds;double[] sampledMatrices;int generation;bool captured;FighterView view;
  [StructLayout(LayoutKind.Explicit)]struct Bits{[FieldOffset(0)]public float Value;[FieldOffset(0)]public int Int;}
  static void Equal(float a,float b){if(new Bits{Value=a}.Int!=new Bits{Value=b}.Int)throw new InvalidDataException("Original source float changed");}
  static void Hash(byte[] bytes,string expected){using(var sha=SHA256.Create()){var hash=sha.ComputeHash(bytes);var text=BitConverter.ToString(hash).Replace("-","").ToLowerInvariant();if(text!=expected)throw new InvalidDataException("Frozen source/metadata hash differs");}}
  public IEnumerator Warmup(){if(IsWarm)yield break;int ticket=generation;yield return null;if(ticket!=generation||IsWarm)yield break;
   if(!sourceSkin||!sourceSkin.sharedMesh||!originalMeshFixture||!compactFixture||!allInfluencesFixture||!originalBoneNames)throw new InvalidOperationException("Assign frozen source fixture assets under visible loading");
   var raw=originalMeshFixture.bytes;var packed=compactFixture.bytes;var hullBytes=allInfluencesFixture.bytes;Hash(raw,MeshSha);Hash(packed,CompactSha);Hash(hullBytes,HullSha);
   var actorView=sourceSkin.GetComponentInParent<FighterView>();if(!actorView)throw new InvalidOperationException("Use the actual production FighterView actor");var mesh=sourceSkin.sharedMesh;if(mesh.blendShapeCount!=0)throw new InvalidOperationException("This narrow review kernel supports the original linear-skin fixture, not morph deformation");var positions=mesh.vertices;var sourceWeights=mesh.boneWeights;var triangles=mesh.triangles;var originalBinds=mesh.bindposes;var sourceBones=sourceSkin.bones;
   V[] points;int[] boneIds;double[] weights;
   using(var r=new BinaryReader(new MemoryStream(raw,false))){int nv=r.ReadInt32(),ni=r.ReadInt32(),nb=r.ReadInt32();if(nv!=57025||ni!=299997||nb!=67||positions.Length!=nv||triangles.Length!=ni||sourceWeights.Length!=nv||originalBinds.Length!=nb||sourceBones.Length!=nb)throw new InvalidDataException("Expected approved original100k Sailor source");points=new V[nv];boneIds=new int[nv*4];weights=new double[nv*4];
    for(int i=0;i<nv;i++){float x=r.ReadSingle(),y=r.ReadSingle(),z=r.ReadSingle();Equal(x,positions[i].x);Equal(y,positions[i].y);Equal(z,positions[i].z);points[i]=new V(x,y,z);}
    for(int i=0;i<nv;i++){int b0=r.ReadInt32(),b1=r.ReadInt32(),b2=r.ReadInt32(),b3=r.ReadInt32();float w0=r.ReadSingle(),w1=r.ReadSingle(),w2=r.ReadSingle(),w3=r.ReadSingle();var w=sourceWeights[i];if(w.boneIndex0!=b0||w.boneIndex1!=b1||w.boneIndex2!=b2||w.boneIndex3!=b3)throw new InvalidDataException("Original bone indexing differs");Equal(w0,w.weight0);Equal(w1,w.weight1);Equal(w2,w.weight2);Equal(w3,w.weight3);int j=i*4;boneIds[j]=b0;boneIds[j+1]=b1;boneIds[j+2]=b2;boneIds[j+3]=b3;weights[j]=w0;weights[j+1]=w1;weights[j+2]=w2;weights[j+3]=w3;}
    for(int i=0;i<nb;i++)for(int row=0;row<4;row++)for(int col=0;col<4;col++)Equal(r.ReadSingle(),originalBinds[i][row,col]);
    for(int i=0;i<ni;i++)if(r.ReadInt32()!=triangles[i])throw new InvalidDataException("Original triangle topology differs");if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Source trailing bytes");
   }
   CompactNode[] nodes;int[] order,leafVertices;
   using(var r=new BinaryReader(new MemoryStream(packed,false))){int n=r.ReadInt32(),o=r.ReadInt32(),v=r.ReadInt32();if(n!=16383||o!=99999||v!=122524)throw new InvalidDataException("Frozen compact topology dimensions");nodes=new CompactNode[n];order=new int[o];leafVertices=new int[v];for(int i=0;i<n;i++)nodes[i]=new CompactNode{Left=r.ReadInt32(),Right=r.ReadInt32(),Start=r.ReadInt32(),Count=r.ReadInt32(),VertexStart=r.ReadInt32(),VertexCount=r.ReadInt32(),OriginalNode=r.ReadInt32()};for(int i=0;i<o;i++)order[i]=r.ReadInt32();for(int i=0;i<v;i++)leafVertices[i]=r.ReadInt32();if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Topology trailing bytes");}
   ValidatePartition(nodes,order,leafVertices,triangles);
   NodeHull[] hulls;BoneHull[] boxes;
   using(var r=new BinaryReader(new MemoryStream(hullBytes,false))){int n=r.ReadInt32(),bc=r.ReadInt32(),nb=r.ReadInt32(),nv=r.ReadInt32();if(n!=nodes.Length||bc!=48441||nb!=sourceBones.Length||nv!=points.Length)throw new InvalidDataException("Frozen all-influence dimensions");hulls=new NodeHull[n];boxes=new BoneHull[bc];for(int i=0;i<n;i++)hulls[i]=new NodeHull{Start=r.ReadInt32(),Count=r.ReadInt32(),SumMin=r.ReadDouble(),SumMax=r.ReadDouble()};for(int i=0;i<bc;i++)boxes[i]=new BoneHull{Bone=r.ReadInt32(),Min=new V(r.ReadDouble(),r.ReadDouble(),r.ReadDouble()),Max=new V(r.ReadDouble(),r.ReadDouble(),r.ReadDouble())};if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Hull trailing bytes");}
   var expectedNames=originalBoneNames.text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);if(expectedNames.Length!=sourceBones.Length)throw new InvalidDataException("Original bone name count");for(int i=0;i<sourceBones.Length;i++)if(!sourceBones[i]||NativeRigBones.CanonicalName(sourceBones[i].name)!=expectedNames[i])throw new InvalidDataException("Original source bone order/name differs");var result=new LazySurface(points,triangles,boneIds,weights,nodes,order,leafVertices,hulls,boxes,sourceBones.Length);
   if(ticket!=generation)yield break;view=actorView;bones=sourceBones;binds=originalBinds;sampledMatrices=new double[bones.Length*16];MainTopology=ContainmentTopology.SailorMainComponentProposal();Surface=result;
  }
  static void ValidatePartition(CompactNode[] nodes,int[] order,int[] vertices,int[] triangles){var seen=new bool[triangles.Length/3];var parents=new int[nodes.Length];for(int n=0;n<nodes.Length;n++){var node=nodes[n];if(node.Count>0){if(node.Start<0||node.Start+node.Count>order.Length||node.VertexStart<0||node.VertexStart+node.VertexCount>vertices.Length)throw new InvalidDataException("Leaf bounds");for(int i=node.Start;i<node.Start+node.Count;i++){int t=order[i];if(t<0||t>=seen.Length||seen[t])throw new InvalidDataException("Triangle partition");seen[t]=true;for(int c=0;c<3;c++){bool found=false;int vertex=triangles[t*3+c];for(int v=node.VertexStart;v<node.VertexStart+node.VertexCount;v++)found|=vertices[v]==vertex;if(!found)throw new InvalidDataException("Original triangle corner omitted");}}}else{if(node.Left<=n||node.Right<=n||node.Left>=nodes.Length||node.Right>=nodes.Length)throw new InvalidDataException("Hierarchy");parents[node.Left]++;parents[node.Right]++;}}foreach(bool value in seen)if(!value)throw new InvalidDataException("Original triangle omitted");for(int n=1;n<parents.Length;n++)if(parents[n]!=1)throw new InvalidDataException("Shared/unreachable node");}
  public void CaptureSampledPose(){if(!IsWarm)throw new InvalidOperationException("Warm source metadata first");if(!view||view.FullPreviewMotion)throw new InvalidOperationException("Probe requires production FullPreviewMotion=false");FillMatrices(sampledMatrices);Surface.SetPose(sampledMatrices);captured=true;}
  void FillMatrices(double[] output){for(int bone=0;bone<bones.Length;bone++){var matrix=bones[bone].localToWorldMatrix*binds[bone];for(int row=0;row<4;row++)for(int col=0;col<4;col++)output[bone*16+row*4+col]=matrix[row,col];}}
  public void WriteCapturedPose(BinaryWriter writer){if(!IsWarm||!captured)throw new InvalidOperationException("Not warm");foreach(double value in sampledMatrices)writer.Write((float)value);}
  public void WriteLivePose(BinaryWriter writer){if(!IsWarm)throw new InvalidOperationException("Not warm");for(int bone=0;bone<bones.Length;bone++){var matrix=bones[bone].localToWorldMatrix*binds[bone];for(int row=0;row<4;row++)for(int col=0;col<4;col++)writer.Write(matrix[row,col]);}}
  // QA-only Unity CPU skin snapshot; not a claim of GPU raster agreement. Call after WaitForEndOfFrame, outside CPU benchmarks.
  public void WriteBakedWorldVertices(BinaryWriter writer){if(!IsWarm)throw new InvalidOperationException("Not warm");var temporary=new Mesh();try{sourceSkin.BakeMesh(temporary,false);var vertices=temporary.vertices;var world=sourceSkin.localToWorldMatrix;writer.Write(vertices.Length);foreach(var vertex in vertices){var point=world.MultiplyPoint3x4(vertex);writer.Write(point.x);writer.Write(point.y);writer.Write(point.z);}}finally{UnityEngine.Object.Destroy(temporary);}}
  public void CancelWarmup(){generation++;}public void Dispose(){generation++;Surface=null;MainTopology=null;captured=false;view=null;bones=null;binds=null;sampledMatrices=null;}
  void OnDestroy(){Dispose();} // OnDisable intentionally retains actor-owned prepared data.
 }
}
